/*
 * Cell temperature from the Enepaq sensor's voltage (issue 62; decided in
 * issue 25's addendum).
 *
 * Each cell block's built-in sensor gives a voltage that falls as the block
 * warms: 2.44 V at -40 C to 1.30 V at 120 C (Enepaq Li-ion Building Block
 * datasheet Rev E, page 3, Table 5, 33 points 5 C apart). A reading in
 * whole millivolts becomes a temperature in 0.1 C by a 1 mV table: linear
 * interpolation between the datasheet points, rounded to the nearest tenth.
 * The table (Src/cell_temp_table.c) is generated by gen_cell_temp.py beside
 * this folder and never edited by hand.
 *
 * This is logic (ADR 0002): no HAL, no RTOS, no clock.
 */
#ifndef CELL_TEMP_H
#define CELL_TEMP_H

#include <stdbool.h>
#include <stdint.h>

/* The sensor's range. A reading outside it is an invalid measurement (spec,
   issue 36: "temperature reading outside 1300-2440 mV"). */
#define CELL_TEMP_MV_MIN 1300u
#define CELL_TEMP_MV_MAX 2440u

/* *deci_c = the temperature of a reading of mv millivolts, in 0.1 C. False,
   leaving *deci_c alone, if mv is outside CELL_TEMP_MV_MIN..MAX. */
bool cell_temp_from_mv(uint16_t mv, int16_t *deci_c);

#endif /* CELL_TEMP_H */
